package org.peirs.service;
import java.util.*;
public final class OptimizationEngine { private OptimizationEngine(){} public record Item(long id,String title,int cost,double score,double annualBenefit,double risk){} public static Map<String,Object> optimize(List<Item> items,int budget,String strategy){if(budget<0)throw new IllegalArgumentException("Budget cannot be negative");int n=items.size();double[][] dp=new double[n+1][budget+1];boolean[][] take=new boolean[n+1][budget+1];for(int i=1;i<=n;i++){Item x=items.get(i-1);double value=switch(strategy){case "RETURN"->x.annualBenefit;case "RISK_ADJUSTED"->x.annualBenefit*(1-x.risk/100.0);default->x.score;};for(int b=0;b<=budget;b++){dp[i][b]=dp[i-1][b];if(x.cost<=b&&dp[i-1][b-x.cost]+value>dp[i][b]){dp[i][b]=dp[i-1][b-x.cost]+value;take[i][b]=true;}}}Set<Long> selected=new HashSet<>();int b=budget;for(int i=n;i>0;i--)if(take[i][b]){Item x=items.get(i-1);selected.add(x.id());b-=x.cost;}List<Map<String,Object>> results=new ArrayList<>();double spend=0,ret=0,score=0,risk=0;for(Item x:items){boolean yes=selected.contains(x.id());if(yes){spend+=x.cost;ret+=x.annualBenefit;score+=x.score;risk+=x.risk;}results.add(Map.of("id",x.id(),"title",x.title(),"selected",yes,"explanation",yes?"Selected by 0/1 dynamic programming to maximize "+strategy.toLowerCase(Locale.ROOT)+" within budget.":"Excluded because the optimal portfolio has greater objective value within budget."));}Map<String,Object> out=new LinkedHashMap<>();out.put("projects",results);out.put("budget",budget);out.put("allocated",spend);out.put("remaining",budget-spend);out.put("expectedAnnualReturn",ret);out.put("averageScore",selected.isEmpty()?0:score/selected.size());out.put("portfolioRisk",selected.isEmpty()?0:risk/selected.size());out.put("strategy",strategy);return out;} }
